#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Content-hash alapú A2A üzenet-deduplikáció.
Újraküldött (retransmitted) A2A üzenetek detektálása és szűrése
a message payload content-hash-ének tárolásával.

Futtatható a repó gyökeréből:
    python a2a_mesh/dedup.py            # self-test
    python a2a_mesh/dedup.py --demo     # interaktív demo

Függőségek: csak stdlib (hashlib, json, time, threading, dataclasses).
"""

from __future__ import annotations

import hashlib
import json
import threading
import time
from dataclasses import dataclass, field
from typing import Any, Dict, Optional, Tuple


# ---------------------------------------------------------------------------
# Hash computation
# ---------------------------------------------------------------------------

_STABLE_FIELDS = (
    "message_id",
    "task_id",
    "role",
    "content",
    "parts",
    "timestamp_sent",
)


def _canonicalize(payload: Dict[str, Any]) -> str:
    """
    Determinisztikus JSON reprezentáció: kulcsok rendezve,
    rekurzív rendezés, ensure_ascii=False, separators tömörítve.
    Kihagyja a futásidejű meta-mezőket (pl. received_at, retry_count).
    """
    def _sort(obj: Any) -> Any:
        if isinstance(obj, dict):
            return {k: _sort(v) for k, v in sorted(obj.items())}
        if isinstance(obj, list):
            return [_sort(v) for v in obj]
        return obj

    filtered = {k: v for k, v in payload.items() if k in _STABLE_FIELDS or k.startswith("content")}
    return json.dumps(_sort(filtered), sort_keys=True, ensure_ascii=False, separators=(",", ":"))


def compute_content_hash(payload: Dict[str, Any]) -> str:
    """SHA-256 a kanonizált payload felett -> hex digest (első 16 byte)."""
    canon = _canonicalize(payload)
    return hashlib.sha256(canon.encode("utf-8")).hexdigest()[:32]


# ---------------------------------------------------------------------------
# Dedup store
# ---------------------------------------------------------------------------

@dataclass
class _Entry:
    hash_val: str
    first_seen: float
    last_seen: float
    hit_count: int = 0
    original_message_id: Optional[str] = None


class DedupStore:
    """
    Thread-safe, TTL-alapú content-hash deduplikációs tároló.

    Minden bejövő A2A üzenethez kiszámoljuk a content-hash-t.
    Ha már láttuk (és nem járt le a TTL), duplikációnak minősül.
    """

    def __init__(
        self,
        ttl_seconds: int = 3600,
        max_entries: int = 50_000,
        cleanup_interval: float = 60.0,
    ) -> None:
        self.ttl_seconds = ttl_seconds
        self.max_entries = max_entries
        self.cleanup_interval = cleanup_interval
        self._store: Dict[str, _Entry] = {}
        self._lock = threading.RLock()
        self._last_cleanup: float = time.monotonic()
        # stats
        self.total_seen = 0
        self.total_duplicates = 0
        self.total_evicted = 0

    # -- public API --

    def check(self, payload: Dict[str, Any]) -> Tuple[bool, Optional[str]]:
        """
        Ellenőrzi a payload-t. Visszatér:
            (is_duplicate, content_hash)

        is_duplicate=True  -> az üzenetet el kell dobni (már feldolgozás alatt / feldolgozva)
        is_duplicate=False -> új üzenet, regisztrálva a store-ban
        """
        h = compute_content_hash(payload)
        now = time.monotonic()

        with self._lock:
            self._maybe_cleanup(now)
            self.total_seen += 1

            entry = self._store.get(h)
            if entry is not None:
                # még érvényes?
                if now - entry.first_seen <= self.ttl_seconds:
                    entry.hit_count += 1
                    entry.last_seen = now
                    self.total_duplicates += 1
                    return True, h
                else:
                    # lejárt, felülírjuk
                    self._store.pop(h, None)

            # új bejegyzés
            self._store[h] = _Entry(
                hash_val=h,
                first_seen=now,
                last_seen=now,
                original_message_id=payload.get("message_id"),
            )

            # overflow védelem
            if len(self._store) > self.max_entries:
                self._evict_oldest()

            return False, h

    def is_duplicate(self, payload: Dict[str, Any]) -> bool:
        """Convenience wrapper: csak a boolean-t adja vissza."""
        dup, _ = self.check(payload)
        return dup

    def stats(self) -> Dict[str, Any]:
        with self._lock:
            return {
                "stored_entries": len(self._store),
                "total_seen": self.total_seen,
                "total_duplicates": self.total_duplicates,
                "total_evicted": self.total_evicted,
                "ttl_seconds": self.ttl_seconds,
                "max_entries": self.max_entries,
            }

    def reset(self) -> None:
        with self._lock:
            self._store.clear()
            self.total_seen = 0
            self.total_duplicates = 0
            self.total_evicted = 0
            self._last_cleanup = time.monotonic()

    # -- internal --

    def _maybe_cleanup(self, now: float) -> None:
        if now - self._last_cleanup < self.cleanup_interval:
            return
        expired = [
            h for h, e in self._store.items()
            if now - e.first_seen > self.ttl_seconds
        ]
        for h in expired:
            self._store.pop(h, None)
        self._last_cleanup = now

    def _evict_oldest(self) -> None:
        if not self._store:
            return
        oldest_hash = min(self._store, key=lambda h: self._store[h].first_seen)
        self._store.pop(oldest_hash, None)
        self.total_evicted += 1


# ---------------------------------------------------------------------------
# A2A message wrapper with dedup integration
# ---------------------------------------------------------------------------

@dataclass
class A2AMessage:
    """Egyszerű A2A üzenet reprezentáció dedup meta-adatokkal."""
    message_id: str
    task_id: str
    role: str
    content: str
    parts: list = field(default_factory=list)
    timestamp_sent: float = field(default_factory=time.time)
    # runtime
    received_at: float = field(default_factory=time.time)
    retry_count: int = 0
    _dedup_hash: Optional[str] = None
    _is_duplicate: bool = False

    def to_payload(self) -> Dict[str, Any]:
        return {
            "message_id": self.message_id,
            "task_id": self.task_id,
            "role": self.role,
            "content": self.content,
            "parts": self.parts,
            "timestamp_sent": self.timestamp_sent,
        }


class DeduplicatingReceiver:
    """
    Wrapper ami a DedupStore-t integrálja az A2A üzenet-fogadásba.
    process() visszaadja az üzenetet ha új, vagy None-t ha duplikátum.
    """

    def __init__(self, store: Optional[DedupStore] = None) -> None:
        self.store = store or DedupStore()

    def process(self, msg: A2AMessage) -> Optional[A2AMessage]:
        """Új üzenet -> visszaadja; duplikátum -> None."""
        is_dup, h = self.store.check(msg.to_payload())
        msg._dedup_hash = h
        msg._is_duplicate = is_dup
        if is_dup:
            return None
        return msg

    def process_payload(self, payload: Dict[str, Any]) -> Optional[Dict[str, Any]]:
        """Raw payload változat."""
        is_dup, h = self.store.check(payload)
        if is_dup:
            return None
        payload["_dedup_hash"] = h
        return payload


# ---------------------------------------------------------------------------
# Self-test / demo
# ---------------------------------------------------------------------------

def _self_test() -> int:
    print("=" * 60)
    print("A2A Content-Hash Deduplication — Self Test")
    print("=" * 60)

    store = DedupStore(ttl_seconds=2, max_entries=100)
    receiver = DeduplicatingReceiver(store)

    # 1. Új üzenet
    msg1 = A2AMessage(
        message_id="msg-001",
        task_id="task-abc",
        role="agent",
        content="Hello from agent A",
        parts=[{"type": "text", "text": "Hello from agent A"}],
    )
    result = receiver.process(msg1)
    assert result is not None, "Első üzenetnek át kell mennie"
    print(f"[OK] Új üzenet elfogadva: hash={msg1._dedup_hash}")

    # 2. Ugyanaz a tartalom, más message_id (retransmit)
    msg2 = A2AMessage(
        message_id="msg-002",  # más ID!
        task_id="task-abc",
        role="agent",
        content="Hello from agent A",  # ugyanaz a content
        parts=[{"type": "text", "text": "Hello from agent A"}],
    )
    result2 = receiver.process(msg2)
    assert result2 is None, "Duplikátumnak el kell dobnia"
    print(f"[OK] Duplikátum eldobva (más message_id, azonos content): hash={msg2._dedup_hash}")

    # 3. Különböző tartalom
    msg3 = A2AMessage(
        message_id="msg-003",
        task_id="task-abc",
        role="agent",
        content="Hello from agent B",
    )
    result3 = receiver.process(msg3)
    assert result3 is not None, "Különböző üzenetnek át kell mennie"
    print(f"[OK] Különböző üzenet elfogadva: hash={msg3._dedup_hash}")

    # 4. Mezősorrend nem számít
    payload_a = {"message_id": "x", "content": "test", "role": "r", "task_id": "t"}
    payload_b = {"role": "r", "task_id": "t", "content": "test", "message_id": "x"}
    ha = compute_content_hash(payload_a)
    hb = compute_content_hash(payload_b)
    assert ha == hb, f"Mezősorrend függetlennek kell lennie: {ha} != {hb}"
    print(f"[OK] Mezősorrend független: hash={ha}")

    # 5. TTL lejárat után újra elfogad
    print("[..] Várakozás TTL lejáratra (2s)...")
    time.sleep(2.5)
    msg4 = A2AMessage(
        message_id="msg-004",
        task_id="task-abc",
        role="agent",
        content="Hello from agent A",
    )
    result4 = receiver.process(msg4)
    assert result4 is not None, "TTL lejárt után újra el kell fogadni"
    print(f"[OK] TTL lejárat után újra elfogadva: hash={msg4._dedup_hash}")

    # 6. Statisztikák
    s = store.stats()
    print(f"\nStatisztikák: {json.dumps(s, indent=2)}")
    assert s["total_duplicates"] >= 1, "Legalább 1 duplikátumnak kell lennie"
    assert s["total_seen"] == 4, f"4 üzenetnek kellett volna: {s['total_seen']}"

    # 7. Thread-safety stress test
    print("\n[--] Thread-safety stress test (1000 konkurrens üzenet, 10 szál)...")
    store2 = DedupStore(ttl_seconds=60, max_entries=10000)
    errors = []

    def worker(seed: int) -> None:
        for i in range(100):
            payload = {"message_id": f"m-{seed}-{i}", "content": f"c-{i % 5}", "role": "r", "task_id": "t"}
            try:
                store2.check(payload)
            except Exception as e:
                errors.append(str(e))

    threads = [threading.Thread(target=worker, args=(s,)) for s in range(10)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert not errors, f"Thread hibák: {errors[:3]}"
    s2 = store2.stats()
    print(f"[OK] {s2['total_seen']} üzenet feldolgozva, {s2['total_duplicates']} duplikátum, 0 hiba")

    print("\n" + "=" * 60)
    print("MINDEN TESZT PASZTALT ✓")
    print("=" * 60)
    return 0


def _demo() -> int:
    print("A2A Dedup Demo — írj be üzeneteket, a rendszer szűri a duplikátumokat.")
    print("Parancsok: :stats, :reset, :quit\n")

    receiver = DeduplicatingReceiver(DedupStore(ttl_seconds=30))

    while True:
        try:
            line = input("content> ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\nViszlát!")
            break

        if not line:
            continue
        if line == ":quit":
            break
        if line == ":stats":
            print(json.dumps(receiver.store.stats(), indent=2))
            continue
        if line == ":reset":
            receiver.store.reset()
            print("Store törölve.")
            continue

        msg = A2AMessage(
            message_id=f"demo-{int(time.time()*1000)}",
            task_id="demo-task",
            role="user",
            content=line,
        )
        result = receiver.process(msg)
        if result is None:
            print(f"  ⚠️  DUPLIKÁTUM — eldobva (hash={msg._dedup_hash})")
        else:
            print(f"  ✅  Új üzenet — elfogadva (hash={msg._dedup_hash})")

    return 0


if __name__ == "__main__":
    import sys

    if "--demo" in sys.argv:
        raise SystemExit(_demo())
    raise SystemExit(_self_test())